INSERT INTO public.questions (material_id, soal, pilihan, jawaban_benar, level, penjelasan) VALUES
-- k6-mtk-01
('k6-mtk-01', 'Berapa hasil 4 × ¾?', '{"a":"2","b":"3","c":"4","d":"5"}', 'b', 1, '4 × ¾ = (4×3)/4 = 12/4 = 3. ✅'),
('k6-mtk-01', 'Hasil dari 5 × ½ adalah?', '{"a":"5/2","b":"2/5","c":"1/2","d":"5"}', 'a', 1, '5 × 1/2 = 5/2.'),
('k6-mtk-01', '2 × 1/3 = ...', '{"a":"1/3","b":"3/2","c":"2/3","d":"2/1"}', 'c', 2, '(2/1) × (1/3) = 2/3.'),
('k6-mtk-01', 'Sederhanakan hasil dari 6 × 2/8', '{"a":"12/8","b":"3/2","c":"2/3","d":"1/4"}', 'b', 2, '12/8 dibagi 4 menjadi 3/2.'),
('k6-mtk-01', 'Sebuah kue dipotong 5 bagian. Andi makan 2/5 kue setiap hari selama 2 hari. Berapa kue yang dimakan?', '{"a":"2/5","b":"4/5","c":"5/4","d":"2"}', 'b', 3, '2 x 2/5 = 4/5.'),

-- k6-mtk-02
('k6-mtk-02', 'Menurut sifat komutatif, ¼ × 5 sama dengan...', '{"a":"4 × 1/5","b":"5 × ¼","c":"1/5 × 4","d":"4/5"}', 'b', 1, 'Tinggal dibalik urutannya: 5 × ¼.'),
('k6-mtk-02', 'Berapa ⅓ × 6?', '{"a":"3","b":"4","c":"2","d":"6"}', 'c', 1, 'Sama dengan 6/3 = 2.'),
('k6-mtk-02', 'Pita ⅕ meter dipotong 10 kali. Total panjang pita?', '{"a":"5 meter","b":"2 meter","c":"10 meter","d":"1/2 meter"}', 'b', 2, '10 × 1/5 = 10/5 = 2 meter.'),
('k6-mtk-02', 'Mana yang hasilnya paling besar?', '{"a":"2 × 1/3","b":"4 × 1/5","c":"3 × 1/2","d":"1 × 1/2"}', 'c', 2, '3/2 = 1.5. Ini yang terbesar.'),
('k6-mtk-02', 'Rina beli 8 botol madu, tiap botol isinya ⅜ liter. Berapa liter madu seluruhnya?', '{"a":"8/3","b":"3","c":"24/8","d":"3"}', 'b', 3, '8 × 3/8 = 24/8 = 3 liter.'),

-- k6-mtk-03
('k6-mtk-03', 'Hasil dari ½ ÷ 2 adalah...', '{"a":"1/4","b":"1","c":"2","d":"4"}', 'a', 1, '½ × ½ = 1/4.'),
('k6-mtk-03', 'Bentuk perkalian dari ⅕ ÷ 3 adalah...', '{"a":"⅕ × 3","b":"⅕ × ⅓","c":"3 × ⅕","d":"1/3 × 5"}', 'b', 1, 'Ubah bagi jadi kali lalu balik angkanya.'),
('k6-mtk-03', 'Jika ¾ kue dibagi untuk 3 orang, tiap orang mendapat?', '{"a":"1/2","b":"1/4","c":"3/4","d":"1/3"}', 'b', 2, '¾ × ⅓ = 3/12 = 1/4.'),
('k6-mtk-03', 'Hasil ⅖ ÷ 4 adalah?', '{"a":"2/5","b":"1/10","c":"5/2","d":"8/5"}', 'b', 2, '⅖ × ¼ = 2/20 = 1/10.'),
('k6-mtk-03', 'Tali panjangnya ⅞ meter akan dibagi rata untuk 7 orang. Berapa panjang tali tiap orang?', '{"a":"1/8 meter","b":"7/8 meter","c":"8/7 meter","d":"1 meter"}', 'a', 3, '⅞ × ⅐ = 7/56 = 1/8.'),

-- k6-mtk-04
('k6-mtk-04', 'Berapa hasil dari 2 ÷ ½?', '{"a":"1","b":"2","c":"4","d":"1/4"}', 'c', 1, '2 × 2/1 = 4.'),
('k6-mtk-04', 'Berapa banyak potongan ¼ di dalam 3?', '{"a":"12","b":"3","c":"4","d":"7"}', 'a', 1, '3 ÷ ¼ = 3 × 4 = 12.'),
('k6-mtk-04', 'Hasil 4 ÷ ⅔ adalah...', '{"a":"6","b":"4","c":"8/3","d":"3/2"}', 'a', 2, '4 × 3/2 = 12/2 = 6.'),
('k6-mtk-04', 'Besi 10 meter dipotong tiap ⅖ meter. Berapa banyak potongan besi?', '{"a":"20","b":"25","c":"4","d":"10"}', 'b', 2, '10 ÷ ⅖ = 10 × 5/2 = 50/2 = 25.'),
('k6-mtk-04', 'Sebuah mobil pakai 1½ liter bensin untuk 1 putaran sirkuit. Punya 6 liter bensin. Berapa putaran yang bisa dilalui?', '{"a":"4","b":"5","c":"6","d":"9"}', 'a', 3, '6 ÷ (3/2) = 6 × 2/3 = 12/3 = 4 putaran.'),

-- k6-mtk-05
('k6-mtk-05', 'Bentuk desimal dari 7/10 adalah?', '{"a":"7.0","b":"0.07","c":"0.7","d":"70"}', 'c', 1, 'Per sepuluh artinya satu angka di belakang koma.'),
('k6-mtk-05', 'Pecahan 25/100 dalam desimal?', '{"a":"0.25","b":"2.5","c":"0.025","d":"25.0"}', 'a', 1, 'Per seratus = dua angka di belakang koma.'),
('k6-mtk-05', 'Bentuk desimal dari ⅕ adalah?', '{"a":"0.1","b":"0.5","c":"0.2","d":"1.5"}', 'c', 2, '1 ÷ 5 = 0.2.'),
('k6-mtk-05', 'Desimal dari pecahan campuran 3½ adalah?', '{"a":"3.2","b":"3.5","c":"3.12","d":"1.5"}', 'b', 2, 'Setengah itu 0.5. Gabung dengan 3 jadi 3.5.'),
('k6-mtk-05', 'Mana pecahan yang nilainya sama dengan 0.75?', '{"a":"½","b":"¾","c":"⅓","d":"⅖"}', 'b', 3, '3 ÷ 4 = 0.75.'),

-- k6-mtk-06
('k6-mtk-06', 'Mana yang lebih besar: 0.5 atau 0.25?', '{"a":"0.25","b":"0.5","c":"Sama","d":"Tidak bisa dinilai"}', 'b', 1, '0.50 lebih besar dari 0.25.'),
('k6-mtk-06', 'Urutan dari yang terkecil: 0.1, 0.05, 0.15', '{"a":"0.05, 0.1, 0.15","b":"0.1, 0.05, 0.15","c":"0.15, 0.1, 0.05","d":"0.05, 0.15, 0.1"}', 'a', 1, '0.05 (terkecil), lalu 0.10, lalu 0.15.'),
('k6-mtk-06', 'Tanda yang tepat: 1.2 ... 1.20', '{"a":">","b":"<","c":"=","d":"+"}', 'c', 2, 'Angka 0 di akhir bilangan desimal tidak mengubah nilai.'),
('k6-mtk-06', 'Andi Rp 2.500, Rina Rp 2.050, Budi Rp 2.550. Siapa paling banyak uangnya?', '{"a":"Andi","b":"Rina","c":"Budi","d":"Sama"}', 'c', 2, '2.550 > 2.500 > 2.050.'),
('k6-mtk-06', 'Di antara 0.8 dan 0.9 terdapat angka?', '{"a":"0.7","b":"0.85","c":"1.0","d":"0.08"}', 'b', 3, '0.85 ada di tengah-tengah 0.80 dan 0.90.'),

-- k6-mtk-07
('k6-mtk-07', 'Apel 4, Jeruk 6. Rasio apel terhadap jeruk?', '{"a":"6:4","b":"4:6","c":"10:4","d":"2:4"}', 'b', 1, 'Sesuai urutan yang disebut: Apel (4) lalu Jeruk (6).'),
('k6-mtk-07', 'Sederhanakan rasio 8:10', '{"a":"4:5","b":"8:5","c":"4:10","d":"16:20"}', 'a', 1, 'Bagi kedua angka dengan 2.'),
('k6-mtk-07', 'Di kelas ada 12 laki-laki dan 18 perempuan. Rasio siswa laki-laki terhadap seluruh siswa?', '{"a":"12:18","b":"12:30","c":"18:30","d":"2:3"}', 'b', 2, 'Total siswa = 30. Rasio Laki-laki:Total = 12:30.'),
('k6-mtk-07', 'Bentuk paling sederhana dari rasio 15:25 adalah?', '{"a":"1:5","b":"3:5","c":"5:3","d":"3:25"}', 'b', 2, 'Sama-sama dibagi 5.'),
('k6-mtk-07', 'Rasio kelereng merah dan biru adalah 3:4. Jika merah ada 9, berapa biru?', '{"a":"8","b":"12","c":"16","d":"10"}', 'b', 3, 'Merah dikali 3 (3x3=9). Maka Biru juga dikali 3 (4x3=12).'),

-- k6-mtk-08
('k6-mtk-08', 'Rasio 3:5 dapat ditulis dalam bentuk pecahan sebagai...', '{"a":"5/3","b":"3/5","c":"3/8","d":"5/8"}', 'b', 1, 'Angka pertama jadi pembilang, angka kedua penyebut.'),
('k6-mtk-08', 'Maksud dari rasio tepung dan gula 2:1 adalah?', '{"a":"Tepung 2 takaran, gula 1 takaran","b":"Tepung 1 takaran, gula 2 takaran","c":"Tepung 2 kg, gula 1 liter","d":"Tepung setengah dari gula"}', 'a', 1, 'Sesuai urutan penyebutan.'),
('k6-mtk-08', 'Ubah pecahan 7/10 jadi notasi rasio.', '{"a":"10:7","b":"7:10","c":"1:7","d":"7:100"}', 'b', 2, 'Pembilang:Penyebut.'),
('k6-mtk-08', 'Panjang meja 150 cm, lebar 100 cm. Rasio panjang : lebar adalah?', '{"a":"3:2","b":"2:3","c":"15:1","d":"1:1.5"}', 'a', 2, '150:100 disederhanakan jadi 3:2.'),
('k6-mtk-08', 'Sebuah kue butuh rasio telur dan terigu 2:5 (dalam butir dan sendok). Kalau pakai 6 telur, butuh terigu berapa?', '{"a":"10","b":"12","c":"15","d":"20"}', 'c', 3, 'Telur kali 3, terigu (5) x 3 = 15.'),

-- k6-mtk-09
('k6-mtk-09', 'Rasio manakah yang senilai dengan 1:2?', '{"a":"2:3","b":"3:6","c":"4:10","d":"5:9"}', 'b', 1, '3:6 jika disederhanakan (bagi 3) menjadi 1:2.'),
('k6-mtk-09', 'Apakah rasio 4:6 senilai dengan 6:9?', '{"a":"Ya","b":"Tidak","c":"Mungkin","d":"Beda jauh"}', 'a', 1, 'Sama-sama bernilai 2:3 jika disederhanakan.'),
('k6-mtk-09', 'Lengkapi rasio senilai: 3:5 = 9:__', '{"a":"10","b":"12","c":"15","d":"25"}', 'c', 2, 'Karena 3x3=9, maka 5x3=15.'),
('k6-mtk-09', 'Campuran cat biru:putih = 2:3. Untuk 8 liter cat biru butuh putih berapa?', '{"a":"10","b":"12","c":"15","d":"6"}', 'b', 2, '2 dikali 4 jadi 8. Maka 3 x 4 = 12 liter.'),
('k6-mtk-09', 'Dalam peta 1 cm = 50 km (1:5.000.000). Jarak asli 150 km, berapa cm di peta?', '{"a":"2 cm","b":"3 cm","c":"4 cm","d":"5 cm"}', 'b', 3, '150 dibagi 50 = 3 cm.')
ON CONFLICT DO NOTHING;
